import { openDB, type IDBPDatabase } from 'idb';

export type Habit = {
  id: string;
  name: string;
  emoji: string;
  color: string;
  createdAt: number;
};

export type HabitLog = {
  id: string;
  habitId: string;
  date: string; // YYYY-MM-DD
};

export type MoodLog = {
  id: string;
  date: string; // YYYY-MM-DD
  score: number; // 1-5
  note?: string;
};

export type AppSettings = {
  darkMode: boolean;
};

const DB_NAME = 'rhythm-db';
const DB_VERSION = 1;

export interface RhythmDB extends IDBPDatabase {
  habits: IDBPStore<Habit, any>;
  habitLogs: IDBPStore<HabitLog, any>;
  moodLogs: IDBPStore<MoodLog, any>;
  settings: IDBPStore<AppSettings, any>;
}

type IDBPStore<T, K> = {
  get(key: K): Promise<T | undefined>;
  getAll(): Promise<T[]>;
  put(value: T): Promise<void>;
  delete(key: K): Promise<void>;
  clear(): Promise<void>;
};

export async function initDB() {
  return openDB<RhythmDB>(DB_NAME, DB_VERSION, {
    upgrade(db) {
      if (!db.objectStoreNames.contains('habits')) {
        db.createObjectStore('habits', { keyPath: 'id' });
      }
      if (!db.objectStoreNames.contains('habitLogs')) {
        const store = db.createObjectStore('habitLogs', { keyPath: 'id' });
        store.createIndex('habitId', 'habitId');
        store.createIndex('date', 'date');
      }
      if (!db.objectStoreNames.contains('moodLogs')) {
        const store = db.createObjectStore('moodLogs', { keyPath: 'id' });
        store.createIndex('date', 'date');
      }
      if (!db.objectStoreNames.contains('settings')) {
        db.createObjectStore('settings', { keyPath: 'id' });
      }
    },
  });
}

import { initDB, type Habit, type HabitLog, type MoodLog, type AppSettings, type RhythmDB } from './db';

let db: RhythmDB;

export async function getDB() {
  if (!db) {
    db = await initDB();
  }
  return db;
}

// --- Habits ---

export async function getHabits(): Promise<Habit[]> {
  const db = await getDB();
  return db.habits.getAll();
}

export async function saveHabit(habit: Habit): Promise<void> {
  const db = await getDB();
  await db.habits.put(habit);
}

export async function deleteHabit(id: string): Promise<void> {
  const db = await getDB();
  await db.habits.delete(id);
  // Also delete logs for this habit
  const logs = await db.habitLogs.getAll();
  for (const log of logs) {
    if (log.habitId === id) {
      await db.habitLogs.delete(log.id);
    }
  }
}

// --- Habit Logs ---

export async function getHabitLogs(): Promise<HabitLog[]> {
  const db = await getDB();
  return db.habitLogs.getAll();
}

export async function toggleHabitLog(habitId: string, date: string): Promise<void> {
  const db = await getDB();
  const logs = await db.habitLogs.getAll();
  const existingLog = logs.find(log => log.habitId === habitId && log.date === date);

  if (existingLog) {
    await db.habitLogs.delete(existingLog.id);
  } else {
    await db.habitLogs.put({
      id: `${habitId}-${date}`,
      habitId,
      date,
    });
  }
}

export async function getHabitLogsByDate(date: string): Promise<string[]> {
  const db = await getDB();
  const logs = await db.habitLogs.getAll();
  return logs
    .filter(log => log.date === date)
    .map(log => log.habitId);
}

// --- Mood ---

export async function getMoodLogs(): Promise<MoodLog[]> {
  const db = await getDB();
  return db.moodLogs.getAll();
}

export async function saveMoodLog(log: MoodLog): Promise<void> {
  const db = await getDB();
  await db.moodLogs.put(log);
}

export async function getMoodLogByDate(date: string): Promise<MoodLog | undefined> {
  const db = await getDB();
  const logs = await db.moodLogs.getAll();
  return logs.find(log => log.date === date);
}

// --- Settings ---

export async function getSettings(): Promise<AppSettings> {
  const db = await getDB();
  const settings = await db.settings.get('user-settings');
  return settings || { darkMode: false };
}

export async function saveSettings(settings: AppSettings): Promise<void> {
  const db = await getDB();
  await db.settings.put({ id: 'user-settings', ...settings });
}

import { HabitLog } from './db';

export function calculateStreaks(habitId: string, logs: HabitLog[]): { current: number; longest: number } {
  const habitLogs = logs
    .filter(log => log.habitId === habitId)
    .map(log => log.date)
    .sort((a, b) => b.localeCompare(a)); // Sort descending (newest first)

  if (habitLogs.length === 0) {
    return { current: 0, longest: 0 };
  }

  let currentStreak = 0;
  let longestStreak = 0;
  let tempStreak = 0;

  // Calculate current streak
  const today = new Date().toISOString().split('T')[0];
  const yesterday = new Date(Date.now() - 86400000).toISOString().split('T')[0];

  // Check if the most recent log is today or yesterday
  if (habitLogs[0] === today || habitLogs[0] === yesterday) {
    let checkDate = new Date(habitLogs[0]);

    // If the first log is today, we start from today. 
    // If it's yesterday, we start from yesterday.
    // But we need to iterate backwards.

    // Let's use a more robust approach:
    // Start from the most recent log and see how many consecutive days we have.

    let lastDate = null;
    for (const dateStr of habitLogs) {
      const currentDate = new Date(dateStr);

      if (lastDate) {
        const diffTime = Math.abs(currentDate.getTime() - lastDate.getTime());
        const diffDays = Math.ceil(diffTime / (1000 * 60 * 60 * 24));

        if (diffDays === 1) {
          tempStreak++;
        } else {
          tempStreak = 1;
        }
      } else {
        tempStreak = 1;
      }

      if (tempStreak > longestStreak) {
        longestStreak = tempStreak;
      }
      lastDate = currentDate;
    }

    // For current streak, we need to ensure it's connected to "now"
    // If the latest log is not today or yesterday, current streak is 0 (or 1 if we just count the latest)
    // Actually, if the latest log is today, current streak is tempStreak.
    // If the latest log is yesterday, current streak is tempStreak.
    // If the latest log is older than yesterday, current streak is 0.

    const latestLogDate = habitLogs[0];
    if (latestLogDate === today || latestLogDate === yesterday) {
        // We need to re-calculate current streak specifically
        // The loop above actually calculates the longest streak if we don't reset.
        // Let's refine.
    }
  }

  // Let's rewrite this more cleanly.
  return calculateStreaksRefined(habitLogs);
}

function calculateStreaksRefined(sortedDates: string[]): { current: number; longest: number } {
  if (sortedDates.length === 0) return { current: 0, longest: 0 };

  let longest = 0;
  let current = 0;

  // Group consecutive dates
  let groups: string[][] = [];
  let currentGroup: string[] = [sortedDates[0]];

  for (let i = 1; i < sortedDates.length; i++) {
    const prev = new Date(sortedDates[i-1]);
    const curr = new Date(sortedDates[i]);
    const diff = (prev.getTime() - curr.getTime()) / (1000 * 60 * 60 * 24);

    if (diff === 1) {
      currentGroup.push(sortedDates[i]);
    } else {
      groups.push(currentGroup);
      currentGroup = [sortedDates[i]];
    }
  }
  groups.push(currentGroup);

  // Longest streak
  longest = Math.max(...groups.map(g => g.length));

  // Current streak
  const today = new Date().toISOString().split('T')[0];
  const yesterday = new Date(Date.now() - 86400000).toISOString().split('T')[0];

  const latestLog = sortedDates[0];
  if (latestLog === today || latestLog === yesterday) {
    // The first group in our sorted (descending) list is the most recent one
    current = groups[0].length;
  } else {
    current = 0;
  }

  return { current, longest };
}

import React, { createContext, useContext, useEffect, useState } from 'react';
import { getSettings, saveSettings } from '../lib/services';

type ThemeContextType = {
  darkMode: boolean;
  toggleDarkMode: () => void;
};

const ThemeContext = createContext<ThemeContextType | undefined>(undefined);

export const ThemeProvider: React.FC<{ children: React.ReactNode }> = ({ children }) => {
  const [darkMode, setDarkMode] = useState(false);

  useEffect(() => {
    const initTheme = async () => {
      const settings = await getSettings();
      setDarkMode(settings.darkMode);
    };
    initTheme();
  }, []);

  useEffect(() => {
    const root = window.document.documentElement;
    if (darkMode) {
      root.classList.add('dark');
    } else {
      root.classList.remove('dark');
    }
    saveSettings({ darkMode });
  }, [darkMode]);

  const toggleDarkMode = () => setDarkMode(prev => !prev);

  return (
    <ThemeContext.Provider value={{ darkMode, toggleDarkMode }}>
      {children}
    </ThemeContext.Provider>
  );
};

export const useTheme = () => {
  const context = useContext(ThemeContext);
  if (context === undefined) {
    throw new Error('useTheme must be used within a ThemeProvider');
  }
  return context;
};

import React, { useState } from 'react';
import { ThemeProvider } from './context/ThemeContext';
import Layout from './components/layout/Layout';
import TodayScreen from './components/today/TodayScreen';
import WeekScreen from './components/week/WeekScreen';
import SettingsScreen from './components/settings/SettingsScreen';

type Tab = 'today' | 'week' | 'settings';

function App() {
  const [activeTab, setActiveTab] = useState<Tab>('today');

  const renderContent = () => {
    switch (activeTab) {
      case 'today':
        return <TodayScreen />;
      case 'week':
        return <WeekScreen />;
      case 'settings':
        return <SettingsScreen />;
      default:
        return <TodayScreen />;
    }
  };

  return (
    <ThemeProvider>
      <div className="min-h-svh flex flex-col items-center">
        <main className="w-full max-w-md flex-1 pb-20">
          {renderContent()}
        </main>
        <Layout activeTab={activeTab} onTabChange={setActiveTab} />
      </div>
    </ThemeProvider>
  );
}

export default App;

import React from 'react';
import { Calendar, CheckCircle2, Settings } from 'lucide-react';

type Tab = 'today' | 'week' | 'settings';

interface LayoutProps {
  activeTab: Tab;
  onTabChange: (tab: Tab) => void;
}

const Layout: React.FC<LayoutProps> = ({ activeTab, onTabChange }) => {
  const tabs: { id: Tab; label: string; icon: React.ReactNode }[] = [
    { id: 'today', label: 'Heute', icon: <CheckCircle2 size={24} /> },
    { id: 'week', label: 'Woche', icon: <Calendar size={24} /> },
    { id: 'settings', label: 'Einstellungen', icon: <Settings size={24} /> },
  ];

  return (
    <nav className="fixed bottom-0 left-0 right-0 bg-[var(--card-bg)] border-t border-[var(--border)] pb-safe-area-inset-bottom">
      <div className="max-w-md mx-auto flex justify-around items-center h-16">
        {tabs.map((tab) => (
          <button
            key={tab.id}
            onClick={() => onTabChange(tab.id)}
            className={`flex flex-col items-center justify-center w-full h-full transition-colors ${
              activeTab === tab.id ? 'text-[var(--accent)]' : 'text-[var(--text-muted)]'
            }`}
          >
            {tab.icon}
            <span className="text-xs mt-1">{tab.label}</span>
          </button>
        ))}
      </div>
    </nav>
  );
};

export default Layout;

import React, { useEffect, useState } from 'react';
import { format } from 'date-fns';
import { de } from 'date-fns/locale';
import { getHabits, getHabitLogs, getHabitLogsByDate, toggleHabitLog, getMoodLogByDate } from '../lib/services';
import { type Habit } from '../lib/db';
import { Plus, Smile } from 'lucide-react';
import HabitItem from './habits/HabitItem';
import MoodSelector from '../mood/MoodSelector';

const TodayScreen: React.FC = () => {
  const [habits, setHabits] = useState<Habit[]>([]);
  const [completedHabitIds, setCompletedHabitIds] = useState<string[]>([]);
  const [today, setToday] = useState(new Date());
  const [mood, setMood] = useState<any>(null);

  const todayStr = format(today, 'yyyy-MM-dd');

  useEffect(() => {
    const loadData = async () => {
      const h = await getHabits();
      setHabits(h);
      const completed = await getHabitLogsByDate(todayStr);
      setCompletedHabitIds(completed);
      const m = await getMoodLogByDate(todayStr);
      setMood(m);
    };
    loadData();
  }, [todayStr]);

  const handleToggleHabit = async (habitId: string) => {
    await toggleHabitLog(habitId, todayStr);
    // Refresh local state
    const completed = await getHabitLogsByDate(todayStr);
    setCompletedHabitIds(completed);
  };

  const progress = habits.length > 0 
    ? Math.round((completedHabitIds.length / habits.length) * 100) 
    : 0;

  return (
    <div className="p-6 space-y-8 animate-in fade-in duration-500">
      <header className="space-y-1">
        <h1 className="text-3xl font-bold tracking-tight">
          {format(today, 'EEEE, d. MMMM', { locale: de })}
        </h1>
        <p className="text-[var(--text-muted)]">
          {completedHabitIds.length} von {habits.length} erledigt
        </p>
        <div className="w-full h-1.5 bg-[var(--border)] rounded-full mt-4 overflow-hidden">
          <div 
            className="h-full bg-[var(--accent)] transition-all duration-500 ease-out"
            style={{ width: `${progress}%` }}
          />
        </div>
      </header>

      <section className="space-y-4">
        <div className="flex items-center justify-between">
          <h2 className="text-xl font-semibold">Deine Habits</h2>
          {/* We'll add a way to manage habits later, maybe in Settings */}
        </div>

        {habits.length === 0 ? (
          <div className="py-12 text-center space-y-4 card">
            <div className="mx-auto w-12 h-12 rounded-full bg-[var(--accent-bg)] flex items-center justify-center text-[var(--accent)]">
              <Plus size={24} />
            </div>
            <p className="text-[var(--text-muted)]">Noch keine Habits angelegt.</p>
          </div>
        ) : (
          <div className="space-y-3">
            {habits.map(habit => (
              <HabitItem 
                key={habit.id} 
                habit={habit} 
                isCompleted={completedHabitIds.includes(habit.id)}
                onToggle={() => handleToggleHabit(habit.id)}
              />
            ))}
          </div>
        )}
      </section>

      <section className="space-y-4">
        <h2 className="text-xl font-semibold">Stimmung</h2>
        <MoodSelector 
          currentMood={mood} 
          onMoodChange={(newMood) => setMood(newMood)} 
        />
      </section>
    </div>
  );
};

export default TodayScreen;

import React from 'react';
import { CheckCircle2, Circle } from 'lucide-react';
import { motion } from 'framer-motion';
import { type Habit } from '../../lib/db';
import { getHabitLogs, calculateStreaks } from '../../lib/services';
import { useEffect, useState } from 'react';

interface HabitItemProps {
  habit: Habit;
  isCompleted: boolean;
  onToggle: () => void;
}

const HabitItem: React.FC<HabitItemProps> = ({ habit, isCompleted, onToggle }) => {
  const [streaks, setStreaks] = useState<{ current: number; longest: number }>({ current: 0, longest: 0 });

  useEffect(() => {
    const loadStreaks = async () => {
      const logs = await getHabitLogs();
      setStreaks(calculateStreaks(habit.id, logs));
    };
    loadStreaks();
  }, [habit.id]);

  return (
    <motion.div
      layout
      initial={{ opacity: 0, y: 10 }}
      animate={{ opacity: 1, y: 0 }}
      className="card p-4 flex items-center justify-between group"
    >
      <div className="flex items-center space-x-4" onClick={onToggle}>
        <button 
          className="focus:outline-none"
          aria-label={isCompleted ? "Habit abwählen" : "Habit abhaken"}
        >
          {isCompleted ? (
            <CheckCircle2 className="text-[var(--accent)]" size={28} />
          ) : (
