import React from 'react';
import { motion } from 'framer-motion';
import { type MoodLog } from '../../lib/db';
import { saveMoodLog } from '../../lib/services';

interface MoodSelectorProps {
  currentMood: MoodLog | undefined;
  onMoodChange: (mood: MoodLog | undefined) => void;
}

const MOODS = [
  { score: 1, emoji: '😢', label: 'Schlecht' },
  { score: 2, emoji: '😕', label: 'Nicht so' },
  { score: 3, emoji: '😐', label: 'Neutral' },
  { score: 4, emoji: '🙂', label: 'Gut' },
  { score: 5, emoji: '🤩', label: 'Super' },
];

const MoodSelector: React.FC<MoodSelectorProps> = ({ currentMood, onMoodChange }) => {
  const [note, setNote] = React.useState(currentMood?.note || '');
  const [isSaving, setIsSaving] = React.useState(false);

  const handleSelect = async (score: number) => {
    setIsSaving(true);
    const date = new Date().toISOString().split('T')[0];

    // If clicking the same mood, we might want to clear it? 
    // For now, let's just update it.
    const newMood: MoodLog = {
      id: `${date}-mood`,
      date,
      score,
      note: note || undefined,
    };

    await saveMoodLog(newMood);
    onMoodChange(newMood);
    setIsSaving(false);
  };

  return (
    <div className="card p-6 space-y-6">
      <div className="flex justify-between items-center">
        <h3 className="font-medium">Wie fühlst du dich heute?</h3>
        {currentMood && (
          <span className="text-sm text-[var(--text-muted)]">
            Gespeichert: {MOODS.find(m => m.score === currentMood.score)?.emoji}
          </span>
        )}
      </div>

      <div className="flex justify-between items-center px-2">
        {MOODS.map((m) => (
          <button
            key={m.score}
            onClick={() => handleSelect(m.score)}
            disabled={isSaving}
            className={`flex flex-col items-center space-y-2 transition-transform active:scale-90 ${
              currentMood?.score === m.score ? 'scale-110' : ''
            }`}
          >
            <span className="text-3xl">{m.emoji}</span>
            <span className={`text-xs ${currentMood?.score === m.score ? 'text-[var(--accent)] font-bold' : 'text-[var(--text-muted)]'}`}>
              {m.label}
            </span>
          </button>
        ))}
      </div>

      <div className="space-y-2">
        <label className="text-xs text-[var(--text-muted)] uppercase tracking-wider">Notiz (optional)</label>
        <textarea
          value={note}
          onChange={(e) => setNote(e.target.value)}
          placeholder="Was war heute los?"
          className="w-full bg-[var(--bg)] border border-[var(--border)] rounded-xl p-3 text-sm focus:outline-none focus:ring-2 focus:ring-[var(--accent)] min-h-[80px] resize-none"
        />
      </div>

      <button
        onClick={() => handleSelect(currentMood?.score || 3)}
        disabled={isSaving}
        className="w-full btn-primary disabled:opacity-50"
      >
        {isSaving ? 'Speichert...' : 'Speichern'}
      </button>
    </div>
  );
};

export default MoodSelector;

import React, { useState } from 'react';
import { useTheme } from '../context/ThemeContext';
import { getHabits, saveHabit, deleteHabit } from '../lib/services';
import { type Habit } from '../lib/db';
import { Plus, Trash2, Moon, Sun } from 'lucide-react';
import HabitForm from './habits/HabitForm';

const SettingsScreen: React.FC = () => {
  const { darkMode, toggleDarkMode } = useTheme();
  const [habits, setHabits] = useState<Habit[]>([]);
  const [isHabitFormOpen, setIsHabitFormOpen] = useState(false);
  const [editingHabit, setEditingHabit] = useState<Habit | null>(null);

  const loadHabits = async () => {
    const h = await getHabits();
    setHabits(h);
  };

  const handleAddOrEditHabit = async (habitData: Omit<Habit, 'id' | 'createdAt'>) => {
    const newHabit: Habit = editingHabit 
      ? { ...editingHabit, ...habitData }
      : {
          id: crypto.randomUUID(),
          createdAt: Date.now(),
          ...habitData
        };

    await saveHabit(newHabit);
    await loadHabits();
    setIsHabitFormOpen(false);
    setEditingHabit(null);
  };

  const handleDeleteHabit = async (id: string) => {
    if (confirm('Möchtest du dieses Habit wirklich löschen? Alle Daten dazu gehen verloren.')) {
      await deleteHabit(id);
      await loadHabits();
    }
  };

  const openEditHabit = (habit: Habit) => {
    setEditingHabit(habit);
    setIsHabitFormOpen(true);
  };

  return (
    <div className="p-6 space-y-8 animate-in fade-in duration-500">
      <header>
        <h1 className="text-3xl font-bold tracking-tight">Einstellungen</h1>
      </header>

      <section className="space-y-4">
        <h2 className="text-xl font-semibold">Erscheinungsbild</h2>
        <div className="card p-4 flex items-center justify-between">
          <div className="flex items-center space-x-3">
            {darkMode ? <Moon size={20} /> : <Sun size={20} />}
            <span>{darkMode ? 'Dark Mode' : 'Light Mode'}</span>
          </div>
          <button 
            onClick={toggleDarkMode}
            className="w-12 h-6 rounded-full bg-[var(--border)] relative transition-colors"
            style={{ backgroundColor: darkMode ? 'var(--accent)' : 'var(--border)' }}
          >
            <div 
              className="absolute top-1 w-4 h-4 rounded-full bg-white transition-all"
              style={{ left: darkMode ? '26px' : '4px' }}
            />
          </button>
        </div>
      </section>

      <section className="space-y-4">
        <div className="flex items-center justify-between">
          <h2 className="text-xl font-semibold">Deine Habits</h2>
          <button 
            onClick={() => {
              setEditingHabit(null);
              setIsHabitFormOpen(true);
            }}
            className="p-2 rounded-full bg-[var(--accent-bg)] text-[var(--accent)]"
          >
            <Plus size={20} />
          </button>
        </div>

        {habits.length === 0 ? (
          <div className="py-12 text-center space-y-4 card">
            <p className="text-[var(--text-muted)]">Noch keine Habits vorhanden.</p>
          </div>
        ) : (
          <div className="space-y-3">
            {habits.map(habit => (
              <div key={habit.id} className="card p-4 flex items-center justify-between">
                <div className="flex items-center space-x-3" onClick={() => openEditHabit(habit)}>
                  <span className="text-xl">{habit.emoji}</span>
                  <span className="font-medium">{habit.name}</span>
                </div>
                <button 
                  onClick={() => handleDeleteHabit(habit.id)}
                  className="text-red-500 p-2"
                >
                  <Trash2 size={18} />
                </button>
              </div>
            ))}
          </div>
        )}
      </section>

      {isHabitFormOpen && (
        <HabitForm 
          habit={editingHabit} 
          onSave={handleAddOrEditHabit} 
          onCancel={() => {
            setIsHabitFormOpen(false);
            setEditingHabit(null);
          }} 
        />
      )}
    </div>
  );
};

export default SettingsScreen;

