import React from 'react';
import { CheckCircle2, Circle } from 'lucide-react';
import { motion } from 'framer-motion';
import { type Habit } from '../../lib/db';
import { calculateStreaks } from '../../lib/services';

interface HabitItemProps {
  habit: Habit;
  isCompleted: boolean;
  onToggle: () => void;
}

const HabitItem: React.FC<HabitItemProps> = ({ habit, isCompleted, onToggle }) => {
  const [streaks, setStreaks] = React.useState<{ current: number; longest: number }>({ current: 0, longest: 0 });

  React.useEffect(() => {
    const loadStreaks = async () => {
      const { getHabitLogs } = await import('../../lib/services');
      const logs = await getHabitLogs();
      setStreaks(calculateStreaks(habit.id, logs));
    };
    loadStreaks();
  }, [habit.id]);

  return (
    <motion.div
      layout
      initial={{ opacity: 0, y: 10 }}
      animate={{ opacity: 1, y: 0 }}
      className="card p-4 flex items-center justify-between group"
    >
      <div className="flex items-center space-x-4" onClick={onToggle}>
        <button 
          className="focus:outline-none"
          aria-label={isCompleted ? "Habit abwählen" : "Habit abhaken"}
        >
          {isCompleted ? (
            <CheckCircle2 className="text-[var(--accent)]" size={28} />
          ) : (
            <Circle className="text-[var(--text-muted)]" size={28} />
          )}
        </button>

        <div className="flex flex-col">
          <div className="flex items-center space-x-2">
            <span className="text-xl">{habit.emoji}</span>
            <span className={`font-medium ${isCompleted ? 'line-through text-[var(--text-muted)]' : ''}`}>
              {habit.name}
            </span>
          </div>
          <div className="text-xs text-[var(--text-muted)] flex space-x-3 mt-0.5">
            <span>🔥 {streaks.current} Tage</span>
            <span>🏆 {streaks.longest} max.</span>
          </div>
        </div>
      </div>

      <div 
        className="w-2 h-8 rounded-full"
        style={{ backgroundColor: habit.color }}
      />
    </motion.div>
  );
};

export default HabitItem;

import React from 'react';
import { type MoodLog } from '../../lib/db';
import { saveMoodLog } from '../../lib/services';

interface MoodSelectorProps {
  currentMood: MoodLog | undefined;
  onMoodChange: (mood: MoodLog | undefined) => void;
}

const MOODS = [
  { score: 1, emoji: '😢', label: 'Schlecht' },
  { score: 2, emoji: '😕', label: 'Nicht so' },
  { score: 3, emoji: '😐', label: 'Neutral' },
  { score: 4, emoji: '🙂', label: 'Gut' },
  { score: 5, emoji: '🤩', label: 'Super' },
];

const MoodSelector: React.FC<MoodSelectorProps> = ({ currentMood, onMoodChange }) => {
  const [note, setNote] = React.useState(currentMood?.note || '');
  const [isSaving, setIsSaving] = React.useState(false);

  const handleSelect = async (score: number) => {
    setIsSaving(true);
    const date = new Date().toISOString().split('T')[0];

    const newMood: MoodLog = {
      id: `${date}-mood`,
      date,
      score,
      note: note || undefined,
    };

    await saveMoodLog(newMood);
    onMoodChange(newMood);
    setIsSaving(false);
  };

  return (
    <div className="card p-6 space-y-6">
      <div className="flex items-center justify-between">
        <h3 className="font-medium">Wie fühlst du dich heute?</h3>
        {currentMood && (
          <span className="text-sm text-[var(--text-muted)]">
            Gespeichert: {MOODS.find(m => m.score === currentMood.score)?.emoji}
          </span>
        )}
      </div>

      <div className="flex justify-between items-center px-2">
        {MOODS.map((m) => (
          <button
            key={m.score}
            onClick={() => handleSelect(m.score)}
            disabled={isSaving}
            className={`flex flex-col items-center space-y-2 transition-transform active:scale-90 ${
              currentMood?.score === m.score ? 'scale-110' : ''
            }`}
          >
            <span className="text-3xl">{m.emoji}</span>
            <span className={`text-xs ${currentMood?.score === m.score ? 'text-[var(--accent)] font-bold' : 'text-[var(--text-muted)]'}`}>
              {m.label}
            </span>
          </button>
        ))}
      </div>

      <div className="space-y-2">
        <label className="text-xs text-[var(--text-muted)] uppercase tracking-wider">Notiz (optional)</label>
        <textarea
          value={note}
          onChange={(e) => setNote(e.target.value)}
          placeholder="Was war heute los?"
          className="w-full bg-[var(--bg)] border border-[var(--border)] rounded-xl p-3 text-sm focus:outline-none focus:ring-2 focus:ring-[var(--accent)] min-h-[80px] resize-none"
        />
      </div>

      <button
        onClick={() => handleSelect(currentMood?.score || 3)}
        disabled={isSaving}
        className="w-full btn-primary disabled:opacity-50"
      >
        {isSaving ? 'Speichert...' : 'Speichern'}
      </button>
    </div>
  );
};

export default MoodSelector;

import React, { useEffect, useState } from 'react';
import { format } from 'date-fns';
import { de } from 'date-fns/locale';
import { getHabits, getHabitLogsByDate, toggleHabitLog, getMoodLogByDate } from '../lib/services';
import { type Habit } from '../lib/db';
import { Plus } from 'lucide-react';
import HabitItem from './habits/HabitItem';
import MoodSelector from '../mood/MoodSelector';

const TodayScreen: React.FC = () => {
  const [habits, setHabits] = useState<Habit[]>([]);
  const [completedHabitIds, setCompletedHabitIds] = useState<string[]>([]);
  const [today] = useState(new Date());
  const [mood, setMood] = useState<any>(null);

  const todayStr = format(today, 'yyyy-MM-dd');

  useEffect(() => {
    const loadData = async () => {
      const h = await getHabits();
      setHabits(h);
      const completed = await getHabitLogsByDate(todayStr);
      setCompletedHabitIds(completed);
      const m = await getMoodLogByDate(todayStr);
      setMood(m);
    };
    loadData();
  }, [todayStr]);

  const handleToggleHabit = async (habitId: string) => {
    await toggleHabitLog(habitId, todayStr);
    // Refresh local state
    const completed = await getHabitLogsByDate(todayStr);
    setCompletedHabitIds(completed);
  };

  const progress = habits.length > 0 
    ? Math.round((completedHabitIds.length / habits.length) * 100) 
    : 0;

  return (
    <div className="p-6 space-y-8 animate-in fade-in duration-500">
      <header className="space-y-1">
        <h1 className="text-3xl font-bold tracking-tight">
          {format(today, 'EEEE, d. MMMM', { locale: de })}
        </h1>
        <p className="text-[var(--text-muted)]">
          {completedHabitIds.length} von {habits.length} erledigt
        </p>
        <div className="w-full h-1.5 bg-[var(--border)] rounded-full mt-4 overflow-hidden">
          <div 
            className="h-full bg-[var(--accent)] transition-all duration-500 ease-out"
            style={{ width: `${progress}%` }}
          />
        </div>
      </header>

      <section className="space-y-4">
        <div className="flex items-center justify-between">
          <h2 className="text-xl font-semibold">Deine Habits</h2>
        </div>

        {habits.length === 0 ? (
          <div className="py-12 text-center space-y-4 card">
            <div className="mx-auto w-12 h-12 rounded-full bg-[var(--accent-bg)] flex items-center justify-center text-[var(--accent)]">
              <Plus size={24} />
            </div>
            <p className="text-[var(--text-muted)]">Noch keine Habits angelegt.</p>
          </div>
        ) : (
          <div className="space-y-3">
            {habits.map(habit => (
              <HabitItem 
                key={habit.id} 
                habit={habit} 
                isCompleted={completedHabitIds.includes(habit.id)}
                onToggle={() => handleToggleHabit(habit.id)}
              />
            ))}
          </div>
        )}
      </section>

      <section className="space-y-4">
        <h2 className="text-xl font-semibold">Stimmung</h2>
        <MoodSelector 
          currentMood={mood} 
          onMoodChange={(newMood) => setMood(newMood)} 
        />
      </section>
    </div>
  );
};

export default TodayScreen;

import React, { useState } from 'react';
import { useTheme } from '../context/ThemeContext';
import { getHabits, saveHabit, deleteHabit } from '../lib/services';
import { type Habit } from '../lib/db';
import { Plus, Trash2 } from 'lucide-react';
import HabitForm from './habits/HabitForm';

interface SettingsScreenProps {}

const SettingsScreen: React.FC<SettingsScreenProps> = () => {
  const { darkMode, toggleDarkMode } = useTheme();
  const [habits, setHabits] = useState<Habit[]>([]);
  const [isHabitFormOpen, setIsHabitFormOpen] = useState(false);
  const [editingHabit, setEditingHabit] = useState<Habit | null>(null);

  const loadHabits = async () => {
    const h = await getHabits();
    setHabits(h);
  };

  // Load habits on mount
  React.useEffect(() => {
    loadHabits();
  }, []);

  const handleAddOrEditHabit = async (habitData: Omit<Habit, 'id' | 'createdAt'>) => {
    const newHabit: Habit = editingHabit 
      ? { ...editingHabit, ...habitData }
      : {
          id: crypto.randomUUID(),
          createdAt: Date.now(),
          ...habitData
        };

    await saveHabit(newHabit);
    await loadHabits();
    setIsHabitFormOpen(false);
    setEditingHabit(null);
  };

  const handleDeleteHabit = async (id: string) => {
    if (confirm('Möchtest du dieses Habit wirklich löschen? Alle Daten dazu gehen verloren.')) {
      await deleteHabit(id);
      await loadHabits();
    }
  };

  const openEditHabit = (habit: Habit) => {
    setEditingHabit(habit);
    setIsHabitFormOpen(true);
  };

  return (
    <div className="p-6 space-y-8 animate-in fade-in duration-500">
      <header>
        <h1 className="text-3xl font-bold tracking-tight">Einstellungen</h1>
      </header>

      <section className="space-y-4">
        <h2 className="text-xl font-semibold">Erscheinungsbild</h2>
        <div className="card p-4 flex items-center justify-between">
          <div className="flex items-center space-x-3">
            {darkMode ? <Moon size={20} /> : <Sun size={20} />}
            <span>{darkMode ? 'Dark Mode' : 'Light Mode'}</span>
          </div>
          <button 
            onClick={toggleDarkMode}
            className="w-12 h-6 rounded-full relative transition-colors"
            style={{ backgroundColor: darkMode ? 'var(--accent)' : 'var(--border)' }}
          >
            <div 
              className="absolute top-1 w-4 h-4 rounded-full bg-white transition-all"
              style={{ left: darkMode ? '26px' : '4px' }}
            />
          </button>
        </div>
      </section>

      <section className="space-y-4">
        <div className="flex items-center justify-between">
          <h2 className="text-xl font-semibold">Deine Habits</h2>
          <button 
            onClick={() => {
              setEditingHabit(null);
              setIsHabitFormOpen(true);
            }}
            className="p-2 rounded-full bg-[var(--accent-bg)] text-[var(--accent)]"
          >
            <Plus size={20} />
          </button>
        </div>

        {habits.length === 0 ? (
          <div className="py-12 text-center space-y-4 card">
            <p className="text-[var(--text-muted)]">Noch keine Habits vorhanden.</p>
          </div>
        ) : (
          <div className="space-y-3">
            {habits.map(habit => (
              <div key={habit.id} className="card p-4 flex items-center justify-between">
                <div className="flex items-center space-x-3" onClick={() => openEditHabit(habit)}>
                  <span className="text-xl">{habit.emoji}</span>
                  <span className="font-medium">{habit.name}</span>
                </div>
                <button 
                  onClick={() => handleDeleteHabit(habit.id)}
                  className="text-red-500 p-2"
                >
                  <Trash2 size={18} />
                </button>
              </div>
            ))}
          </div>
        )}
      </section>

      {isHabitFormOpen && (
        <HabitForm 
          habit={editingHabit} 
          onSave={handleAddOrEditHabit} 
          onCancel={() => {
            setIsHabitFormOpen(false);
            setEditingHabit(null);
          }} 
        />
      )}
    </div>
  );
};

